private static Comparator<PointCostPair> pointCostPairComparator =
    new Comparator<PointCostPair>() {
    public int compare(PointCostPair o1, PointCostPair o2) {
        if (o1 == null) {
            return (o2 == null) ? 0 : +1;
        } else if (o2 == null) {
            return -1;
        }
        return (o1.getCost() < o2.getCost()) ? -1 : ((o1 == o2) ? 0 : +1);
    }
};

